"""Generated files are marked (scripts/generated.py, the guidance note generated-files-are-marked):
the marker in each comment syntax and its place, the declarations in generated.yaml, the check that
fails on a declared output without its marker, a marked file nobody declares and a fresh run that
differs, the lock files it exempts, and the notice an editor shows. Each fixture is a folder that is
no git checkout, which the check reads whole, as it reads the commit hook's copy of the staged tree.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import fake_processes as fake_programs
import generated
import pytest

ROOT = Path(__file__).resolve().parents[1]

# A generator of the fixtures: writes out.toml from src.txt with its marker; with --check, exits 1
# where out.toml differs from what it would write.
GENERATOR = """\
import json
import re
import sys
from pathlib import Path
want = "# Code generated by gen.py write from src.txt. DO NOT EDIT.\\nvalue = " + repr(Path("src.txt").read_text().strip()) + "\\n"
if sys.argv[1:] == ["--check"]:
    if Path("out.toml").read_text() != want:
        print("out.toml: differs from src.txt")
        sys.exit(1)
    sys.exit(0)
Path("out.toml").write_text(want)
"""


def project(tmp_path: Path, files: dict[str, str], declarations: str) -> Path:
    root = tmp_path / "project"
    for name, text in {**files, "generated.yaml": declarations}.items():
        (root / name).parent.mkdir(parents=True, exist_ok=True)
        (root / name).write_text(text, encoding="utf-8")
    return root


def declare(*entries: str) -> str:
    return "generators:\n" + "".join(entries)


def entry(generator: str, source: str, outputs: list[str], how: str = '    held_by: generated.yaml\n') -> str:
    return (f"  - generator: {generator}\n    source: {source}\n    outputs:\n"
            + "".join(f"      - {output}\n" for output in outputs) + how)


def test_the_marker_is_one_line_per_comment_syntax_at_the_first_line_its_format_leaves() -> None:
    assert generated.line("se_plugin.py build", "src/a.md", "html") == (
        "<!-- Code generated by se_plugin.py build from src/a.md. DO NOT EDIT. -->")
    assert generated.line("g", "s", "hash") == "# Code generated by g from s. DO NOT EDIT."
    assert generated.line("g", "s", "slash") == "// Code generated by g from s. DO NOT EDIT."
    # Go's own marker regular expression, which gopls and linters read, matches the `//` line.
    assert re.match(r"^// Code generated .* DO NOT EDIT\.$", generated.line("g", "s", "slash"))
    # The first line; after `#!`, after Markdown front matter.
    assert generated.marker_at("# Code generated by g from s. DO NOT EDIT.\nx = 1\n", "hash") == \
        generated.Marker("g", "s")
    assert generated.marker_at("#!/bin/sh\n# Code generated by g from s.sh. DO NOT EDIT.\n", "hash") == \
        generated.Marker("g", "s.sh")
    front = "---\nname: a\n---\n<!-- Code generated by se_plugin.py build from src/a.md. DO NOT EDIT. -->\nBody\n"
    assert generated.marker_at(front, "html") == generated.Marker("se_plugin.py build", "src/a.md")
    # Anywhere else it marks nothing: a marker quoted in a file's body is no marker.
    assert generated.marker_at("x = 1\n# Code generated by g from s. DO NOT EDIT.\n", "hash") is None
    assert generated.marker_at("# Code generated by g from s.\n", "hash") is None
    # mark places it, and replaces an earlier one, also in a CRLF file.
    assert generated.mark("#!/bin/sh\necho\n", "g", "s", "hash") == (
        "#!/bin/sh\n# Code generated by g from s. DO NOT EDIT.\necho\n")
    again = generated.mark(generated.mark("x = 1\n", "g", "s", "hash"), "h", "t", "hash")
    assert again == "# Code generated by h from t. DO NOT EDIT.\nx = 1\n"
    assert generated.marker_at("# Code generated by g from s. DO NOT EDIT.\r\nx\r\n", "hash") == \
        generated.Marker("g", "s")
    # A format without comments has no syntax: .gitattributes marks it, the generator's spaces as `:`.
    assert generated.syntax_of("a.json") is None and generated.syntax_of("a.txt") is None
    assert generated.syntax_of("hooks/pre-commit", "#!/bin/sh\n") == "hash"
    assert generated.attribute("se_plugin.py build") == "se_plugin.py:build"


def test_a_marked_and_declared_tree_passes(tmp_path: Path) -> None:
    root = project(tmp_path, {
        "out.toml": "# Code generated by gen.py write from src.txt. DO NOT EDIT.\nvalue = 'x'\n",
        "data/a.json": "{}\n",
        ".gitattributes": "/data/*.json linguist-generated generated-by=gen.py:write\n",
        "uv.lock": "version = 1\n",
        "hand.md": "A hand-written note.\n",
    }, declare(entry("gen.py write", "src.txt", ["out.toml", "data/*.json"])))
    assert generated.findings(root, rerun=False) == []


def test_a_declared_output_without_its_marker_fails_naming_the_file_and_the_remedy(tmp_path: Path) -> None:
    root = project(tmp_path, {"out.toml": "value = 'x'\n", "data/a.json": "{}\n"},
                   declare(entry("gen.py write", "src.txt", ["out.toml", "data/*.json"])))
    found = generated.findings(root, rerun=False)
    assert found == [
        "data/a.json: generated by gen.py write, in a format without comments, so .gitattributes marks "
        "it: add `data/a.json linguist-generated generated-by=gen.py:write` (or a pattern that covers it)",
        "out.toml: generated by gen.py write but lacks its marker `# Code generated by gen.py write from "
        "src.txt. DO NOT EDIT.`; run gen.py write, which writes it, and edit src.txt instead of the file",
    ]


def test_a_marker_that_names_another_generator_fails(tmp_path: Path) -> None:
    root = project(tmp_path, {"out.toml": "# Code generated by other.py from src.txt. DO NOT EDIT.\n"},
                   declare(entry("gen.py write", "src.txt", ["out.toml"])))
    [found] = generated.findings(root, rerun=False)
    assert found.startswith("out.toml: its marker names other.py, but generated.yaml declares it "
                            "gen.py write's output")


def test_a_marked_file_no_declaration_covers_fails(tmp_path: Path) -> None:
    root = project(tmp_path, {
        "stray.yaml": "# Code generated by gen.py write from src.txt. DO NOT EDIT.\na: 1\n",
        "other.json": "{}\n",
        ".gitattributes": "other.json linguist-generated generated-by=gen.py:write\n",
        "out.toml": "# Code generated by gen.py write from src.txt. DO NOT EDIT.\n",
    }, declare(entry("gen.py write", "src.txt", ["out.toml"])))
    assert generated.findings(root, rerun=False) == [
        "other.json: .gitattributes marks it as generated by gen.py:write, which generated.yaml does not "
        "declare it of; declare it, or remove the attribute",
        "stray.yaml: marked as generated by gen.py write, which generated.yaml does not declare it of; "
        "declare it among gen.py write's outputs, or remove the marker from a hand-written file",
    ]


def test_a_hand_edited_generated_file_fails_its_fresh_run(tmp_path: Path, fake_processes) -> None:
    fake_processes.on("gen.py", fake_programs.run_script)  # the planted generator, in this process
    check = f'    check: [{json.dumps(sys.executable)}, "gen.py", "--check"]\n'
    root = project(tmp_path, {"gen.py": GENERATOR, "src.txt": "x\n"},
                   declare(entry("gen.py write", "src.txt", ["out.toml"], check)))
    generated.run_check(root, (sys.executable, "gen.py"))  # the generator writes its output
    assert generated.findings(root) == []
    out = root / "out.toml"
    out.write_text(out.read_text() + "edited = true\n")
    [found] = generated.findings(root)
    assert found.startswith("gen.py write: a fresh run does not reproduce its outputs (")
    assert "exits 1: out.toml: differs from src.txt); run gen.py write and commit what it writes" in found
    # Without the fresh run, as at commit, the edit is not seen: its marker still stands.
    assert generated.findings(root, rerun=False) == []


def test_lock_files_are_exempt_and_never_declared(tmp_path: Path) -> None:
    root = project(tmp_path, {"uv.lock": "version = 1\n", "sub/go.sum": "x h1:y\n", "package-lock.json": "{}\n"},
                   declare(entry("gen.py write", "src.txt", ["uv.lock"])))
    assert generated.findings(root, rerun=False) == [
        "uv.lock: uv's lock file, exempt from the marker; remove it from generated.yaml"]
    assert generated.notice(root, "sub/go.sum") == "generated by go; edit what it locks, then run it"


def test_the_declarations_are_held_to_their_shape(tmp_path: Path) -> None:
    root = project(tmp_path, {"out.toml": "# Code generated by gen.py write from src.txt. DO NOT EDIT.\n"},
                   declare(entry("gen.py write", "src.txt", ["out.toml", "gone/*.toml"],
                                 "    held_by: tests/missing.py\n")))
    assert generated.findings(root, rerun=False) == [
        "generated.yaml: gen.py write declares gone/*.toml, which matches no tracked file; remove it, or "
        "run the generator and commit what it writes",
        "generated.yaml: gen.py write is held by tests/missing.py, which does not exist; name the test or "
        "workflow that reruns it",
    ]
    for how, refused in (("", "name exactly one of `check`, `held_by` and `unchecked`"),
                         ('    held_by: a\n    unchecked: "b"\n', "name exactly one of"),
                         ("    kind: x\n    held_by: a\n", r"unknown keys \['kind'\]")):
        (root / "generated.yaml").write_text(declare(entry("gen.py write", "src.txt", ["out.toml"], how)))
        with pytest.raises(generated.DeclarationError, match=refused):
            generated.load(root)
    (root / "generated.yaml").write_text(declare(entry("a", "s", ["x.txt"]), entry("a", "s", ["y.txt"])))
    with pytest.raises(generated.DeclarationError, match="a is declared twice"):
        generated.load(root)


def test_the_notice_names_the_generator_and_what_to_edit(tmp_path: Path) -> None:
    root = project(tmp_path, {
        "out.toml": "# Code generated by gen.py write from src.txt. DO NOT EDIT.\n",
        "data/a.json": "{}\n", "hand.md": "Hand.\n",
    }, declare(entry("gen.py write", "src.txt", ["out.toml", "data/*.json"])))
    assert generated.notice(root, "out.toml") == "generated by gen.py write from src.txt; edit src.txt"
    assert generated.notice(root, "data/a.json") == "generated by gen.py write from src.txt; edit src.txt"
    assert generated.notice(root, "hand.md") is None
    assert generated.main(["--root", str(root), "notice", "hand.md"]) == 1


def test_the_command_exits_by_its_verdict(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    root = project(tmp_path, {"out.toml": "value = 1\n"}, declare(entry("gen.py write", "src.txt", ["out.toml"])))
    assert generated.main(["--root", str(root), "check", "--no-rerun"]) == 1
    assert "out.toml: generated by gen.py write but lacks its marker" in capsys.readouterr().out
    (root / "out.toml").write_text(generated.mark("value = 1\n", "gen.py write", "src.txt", "hash"))
    assert generated.main(["--root", str(root), "check", "--no-rerun"]) == 0
    (root / "generated.yaml").write_text("generators: 3\n")
    assert generated.main(["--root", str(root), "check"]) == 2


def se_files() -> list[str]:
    """SE's checkout's files as a fresh clone holds them: without what .gitignore ignores."""
    ignored = {".git", ".se", ".venv", ".pytest_cache", "__pycache__"}
    return sorted(path.relative_to(ROOT).as_posix() for path in ROOT.rglob("*")
                  if path.is_file() and not ignored & set(path.relative_to(ROOT).parts)
                  and path.suffix != ".pyc" and path.name != ".public-check.local")


def test_se_marks_and_declares_every_generated_file() -> None:
    """SE's own tree passes the check's markers and declarations; CI's hygiene step adds the fresh
    runs. Every file a generator writes carries the marker, or its .gitattributes line."""
    assert generated.findings(ROOT, rerun=False, files=se_files()) == []
    assert generated.notice(ROOT, "agents/worker.md") == (
        "generated by se_plugin.py build from src/agents/worker.md; edit src/agents/worker.md")


def test_a_regenerable_output_carries_the_merge_driver_and_only_it(tmp_path: Path) -> None:
    regenerate = '    held_by: generated.yaml\n    regenerate: ["python", "gen.py"]\n'
    files = {"out.toml": "# Code generated by gen.py write from src.txt. DO NOT EDIT.\n", "data/a.json": "{}\n",
             "data/b.json": "{}\n", "hand.json": "{}\n",
             ".gitattributes": "/data/*.json linguist-generated generated-by=gen.py:write\n"}
    root = project(tmp_path, files, declare(entry("gen.py write", "src.txt", ["out.toml", "data/*.json"], regenerate)))
    assert generated.findings(root, rerun=False) == [
        ".gitattributes: gen.py write regenerates out.toml on a merge, but out.toml lack the merge driver; "
        "add `/out.toml merge=se-generated`",
        ".gitattributes: gen.py write regenerates data/*.json on a merge, but data/a.json and 1 more lack "
        "the merge driver; add `/data/*.json merge=se-generated`",
    ]
    (root / ".gitattributes").write_text(files[".gitattributes"] + "/out.toml merge=se-generated\n"
                                         "/data/*.json merge=se-generated\n/hand.json merge=se-generated\n")
    assert generated.findings(root, rerun=False) == [
        "hand.json: .gitattributes gives it the merge driver se-generated, but no generator generated.yaml "
        "declares it of has `regenerate`, so a merge would keep one side; declare its `regenerate`, or "
        "remove the attribute"]
    (root / "generated.yaml").write_text(declare(entry("gen.py write", "src.txt", ["out.toml"],
                                                       '    held_by: generated.yaml\n    regenerate: "gen.py"\n')))
    with pytest.raises(generated.DeclarationError, match="`regenerate` is a command, a list of words"):
        generated.load(root)


FAILING = "import sys\nprint('the source does not parse')\nsys.exit(3)\n"


def checkout(tmp_path: Path, files: dict[str, str]) -> Path:
    """A git checkout (the door's fake) with `files` committed."""
    import fake_git
    import git_door

    root = fake_git.init(tmp_path / "checkout")
    for name, text in files.items():
        (root / name).parent.mkdir(parents=True, exist_ok=True)
        (root / name).write_text(text, encoding="utf-8")
    for arguments in (["add", "-A"], ["-c", "user.name=alice", "-c", "user.email=alice", "commit", "-q", "-m", "base"]):
        assert git_door.run(*arguments, root=root).returncode == 0
    return root


@pytest.mark.usefixtures("fake_git_door")
def test_regenerate_stages_what_each_command_rewrote_and_leaves_an_earlier_edit_out(
        tmp_path: Path, fake_processes) -> None:
    import git_door

    fake_processes.on("gen.py", fake_programs.run_script).on("fail.py", fake_programs.run_script)
    root = checkout(tmp_path, {"gen.py": GENERATOR, "fail.py": FAILING, "src.txt": "x\n", "notes.txt": "a\n",
                               "out.toml": "stale\n"})
    (root / "notes.txt").write_text("edited, not staged\n", encoding="utf-8")
    (root / "src.txt").write_text("y\n", encoding="utf-8")
    assert git_door.run("add", "src.txt", root=root).returncode == 0  # the merge's tree, staged
    done = generated.regenerate(root, [("gen.py write", (sys.executable, "gen.py"))])
    assert done == [("gen.py write", ["out.toml"])]
    assert git_door.run("status", "--porcelain", root=root).stdout == " M notes.txt\nM  out.toml\nM  src.txt\n"
    assert (root / "out.toml").read_text().endswith("value = 'y'\n")
    with pytest.raises(generated.RegenerateError) as failed:
        generated.regenerate(root, [("checker", (sys.executable, "fail.py"))])
    assert failed.value.what == f"checker ({sys.executable} fail.py)"
    assert failed.value.output == "the source does not parse"


@pytest.mark.usefixtures("fake_git_door")
def test_regenerate_while_merging_runs_only_during_a_merge(tmp_path: Path, fake_processes, capsys) -> None:
    fake_processes.on("gen.py", fake_programs.run_script)
    regenerate = f'    held_by: generated.yaml\n    regenerate: [{json.dumps(sys.executable)}, "gen.py"]\n'
    root = checkout(tmp_path, {"gen.py": GENERATOR, "src.txt": "x\n", "out.toml": "stale\n",
                               "generated.yaml": declare(entry("gen.py write", "src.txt", ["out.toml"], regenerate))})
    assert generated.main(["--root", str(root), "regenerate", "--merging"]) == 0
    assert (root / "out.toml").read_text() == "stale\n" and not fake_processes.calls
    assert generated.main(["--root", str(root), "regenerate"]) == 0
    assert capsys.readouterr().out == "generated.py: gen.py write regenerated out.toml\n"
